#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

long long gcd(long long a, long long b)
{
    while (b)
    {
        long long r = a % b;
        a = b;
        b = r;
    }
    return a;
}
int main(void)
{
    int n;
    long long weights = 0, weighted = 0, w, v;
    if (scanf("%d", &n) != 1)
        return 1;
    for (int i = 0; i < n; ++i)
    {
        if (scanf("%lld%lld", &w, &v) != 2)
            return 1;
        weights += w;
        weighted += w * v; // 先按票数给积分加权。
    }
    long long g = gcd(weighted, weights);
    printf("%lld %lld\n", weighted / g, weights / g);
    return 0;
}

