#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int sg[1000001];
int main(void)
{
    int n, moves[3] = {1, 3, 4};
    if (scanf("%d", &n) != 1)
        return 1;
    for (int x = 1; x <= n; ++x)
    {
        int seen[4] = {0};
        for (int j = 0; j < 3; ++j)
            if (x >= moves[j])
                seen[sg[x - moves[j]]] = 1;
        while (sg[x] < 4 && seen[sg[x]])
            ++sg[x]; // 最多三个后继，mex不超过3。
    }
    printf("%d\n", sg[n]);
    return 0;
}

