#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static long long a[2000];
int main(void)
{
    int n;
    long long answer = 0;
    if (scanf("%d", &n) != 1)
        return 1;
    for (int i = 0; i < n; ++i)
        if (scanf("%lld", &a[i]) != 1)
            return 1;
    while (n > 1)
    {
        int x = 0;
        for (int i = 1; i < n; ++i)
            if (a[i] < a[x])
                x = i;
        long long first = a[x];
        a[x] = a[--n];
        x = 0;
        for (int i = 1; i < n; ++i)
            if (a[i] < a[x])
                x = i;
        a[x] += first;
        answer += a[x];
    }
    printf("%lld\n", answer);
    return 0;
}

