#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    unsigned int basis[30] = {0}, x, answer = 0;
    int n;
    if (scanf("%d", &n) != 1)
        return 1;
    for (int i = 0; i < n; ++i)
    {
        if (scanf("%u", &x) != 1)
            return 1;
        for (int b = 29; b >= 0; --b)
        {
            if (!(x & (1u << b)))
                continue;
            if (!basis[b])
            {
                basis[b] = x;
                break;
            }
            x ^= basis[b];
        }
    }
    for (int b = 29; b >= 0; --b)
        if ((answer ^ basis[b]) > answer)
            answer ^= basis[b];
    printf("%u\n", answer);
    return 0;
}

