static long long a[500], b[500], c[999];
int main(void)
{
    int n, m;
    if (scanf("%d%d", &n, &m) != 2)
        return 1;
    for (int i = 0; i < n; ++i)
        if (scanf("%lld", &a[i]) != 1)
            return 1;
    for (int j = 0; j < m; ++j)
        if (scanf("%lld", &b[j]) != 1)
            return 1;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j)
            c[i + j] += a[i] * b[j];
    for (int k = 0; k < n + m - 1; ++k)
        printf("%s%lld", k ? " " : "", c[k]);
    putchar('\n');
    return 0;
}

