#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    char a[1001], b[1001], result[1002];
    if (scanf("%1000s%1000s", a, b) != 2)
        return 1;
    int i = (int)strlen(a) - 1, j = (int)strlen(b) - 1, n = 0, carry = 0;
    while (i >= 0 || j >= 0 || carry)
    {
        int value = carry;
        if (i >= 0)
            value += a[i--] - '0';
        if (j >= 0)
            value += b[j--] - '0';
        result[n++] = (char)('0' + value % 10);
        carry = value / 10;
    }
    while (n > 1 && result[n - 1] == '0')
        --n;
    while (n > 0)
        putchar(result[--n]);
    putchar('\n');
    return 0;
}

