#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int reach[200][200];
int node(int x)
{
    return 2 * (abs(x) - 1) + (x < 0);
}
int main(void)
{
    int n, m, a, b;
    if (scanf("%d%d", &n, &m) != 2)
        return 1;
    for (int i = 0; i < m; ++i)
    {
        if (scanf("%d%d", &a, &b) != 2)
            return 1;
        a = node(a);
        b = node(b);
        reach[a ^ 1][b] = reach[b ^ 1][a] = 1;
    }
    for (int k = 0; k < 2 * n; ++k)
        for (int i = 0; i < 2 * n; ++i)
            for (int j = 0; j < 2 * n; ++j)
                reach[i][j] |= reach[i][k] && reach[k][j];
    for (int i = 0; i < n; ++i)
        if (reach[2 * i][2 * i + 1] && reach[2 * i + 1][2 * i])
        {
            puts("NO");
            return 0;
        }
    puts("YES");
    return 0;
}

