}
int main(void)
{
    long long a, b, c, d;
    if (scanf("%lld%lld%lld%lld", &a, &b, &c, &d) != 4)
        return 1;
    long long numerator = a * (c + d);
    long long denominator = numerator + c * (a + b);
    long long g = gcd(numerator, denominator);
    printf("%lld %lld\n", numerator / g, denominator / g);
    return 0;
}

